         <div class="form-field">
           <fieldset>
             <legend>2. Which languages are commonly used for systems programming?</legend>
             <div class="choices">
               <label class="choice"><input type="checkbox" name="q2" value="C"> C</label>
               <label class="choice"><input type="checkbox" name="q2" value="Rust"> Rust</label>
               <label class="choice"><input type="checkbox" name="q2" value="Python"> Python</label>
               <label class="choice"><input type="checkbox" name="q2" value="Assembly"> Assembly</label>
             </div>
           </fieldset>
         </div>

         <div class="form-field">
           <fieldset>
             <legend>3. Which of these are query languages or formats for requesting data?</legend>
             <div class="choices">
               <label class="choice"><input type="checkbox" name="q3" value="SQL"> SQL</label>
               <label class="choice"><input type="checkbox" name="q3" value="GraphQL"> GraphQL</label>
               <label class="choice"><input type="checkbox" name="q3" value="Java"> Java</label>
               <label class="choice"><input type="checkbox" name="q3" value="XQuery"> XQuery</label>
             </div>
           </fieldset>
         </div>

         <div class="actions">
           <button type="submit">Submit quiz</button>
           <p id="results" class="results" aria-live="polite"></p>
         </div>
       </form>
     </section>
   </main>

   <script>
     const answerKey = {
       q1: ["CSS", "Sass"],
       q2: ["C", "Rust", "Assembly"],
       q3: ["SQL", "GraphQL", "XQuery"]
     };

     const form = document.getElementById("quiz-form");
     const results = document.getElementById("results");

     function getSelectedValues(name) {
       return Array.from(form.querySelectorAll(`input[name="${name}"]:checked`)).map((input) => input.value).sort();
     }

     function matchesAnswer(selected, expected) {
       return selected.length === expected.length && selected.every((value, index) => value === expected[index]);
     }

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       let score = 0;
       const total = Object.keys(answerKey).length;

       Object.entries(answerKey).forEach(([question, expected]) => {
         const selected = getSelectedValues(question);

         if (matchesAnswer(selected, [...expected].sort())) {
           score += 1;
         }
       });

       results.className = "results " + (score === total ? "success" : "error");
       results.textContent = `You got ${score} out of ${total} question${total === 1 ? "" : "s"} correct.`;
     });
   </script>
 </body>
 </html>

